<?php use App\Core\Helpers as H;$isCustom=($listingType??'product')==='custom_design'; ?><header class="dashboard-heading"><h1>Post “<?=H::e($p['title'])?>”</h1><p class="muted"><?=$isCustom?'Custom Design':'Product'?></p></header>
<form class="card" method="post"><input type="hidden" name="_csrf" value="<?=H::csrf()?>"><fieldset><legend>Platforms</legend><?php foreach($connections as $c):?><label><input type="checkbox" name="platforms[]" value="<?=H::e($c['platform'])?>" <?=$c['connection_status']==='connected'?'':'disabled'?>> <?=H::e(ucfirst($c['platform']))?> — <?=H::e($c['connection_status'])?></label><?php endforeach;?></fieldset><fieldset><legend>Approved preview image</legend><?php foreach($images as $i):?><label><input required type="radio" name="image_id" value="<?=(int)$i['id']?>"><img style="max-width:140px" src="<?=H::e(H::assetUrl($i['image_path']))?>" alt="<?=H::e($isCustom?'Custom Design preview':'Product preview')?>"></label><?php endforeach;?></fieldset><label>Caption / description<textarea name="caption" maxlength="5000" rows="10" required><?=H::e($caption)?></textarea></label><button class="btn" type="submit">Post Now</button></form>
